let interval = context.get('interval') || 10;
let timer = context.get('timer');
let visualTimer = context.get('visualTimer');
let isRunning = context.get('isRunning') || false;

function clearTimers() {
    if (timer) clearTimeout(timer);
    if (visualTimer) clearInterval(visualTimer);
}

if (msg.type === "new_queue") {
    if (isRunning) return null;
    isRunning = true;
    interval = 10;
} else if (msg.type === "sync_success") {
    global.set("server_online", true);
    interval = 10; 
    clearTimers();
    node.send({ topic: "SELECT * FROM attendance LIMIT 50" });
    context.set('isRunning', true);
    return null;
} else if (msg.type === "sync_fail") {
    global.set("server_online", false);
    interval = Math.min(interval * 2, 300);
} else if (msg.type === "queue_empty") {
    isRunning = false;
    clearTimers();
    context.set('isRunning', false);
    node.status({fill:"grey", shape:"dot", text:"Idle - Queue Empty"});
    return null;
}

clearTimers();
let targetTime = Date.now() + (interval * 1000);

visualTimer = setInterval(() => {
    let remaining = Math.ceil((targetTime - Date.now()) / 1000);
    if (remaining >= 0) {
        node.status({fill:"blue", shape:"ring", text: "Next check in " + remaining + "s"});
    } else {
        clearInterval(visualTimer);
    }
}, 1000);

timer = setTimeout(() => {
    node.send({ topic: "SELECT * FROM attendance LIMIT 50" });
}, interval * 1000);

context.set('interval', interval);
context.set('timer', timer);
context.set('visualTimer', visualTimer);
context.set('isRunning', isRunning);
return null;

if (!msg.payload || msg.payload.length === 0) {
    return [null, { type: "queue_empty" }];
}

let events = msg.payload;

msg.event_ids = events.map(e => e.id);

msg.payload = {
    "deviceUid": global.get("gateway_key"),
    "events": events.map(e => ({
        "cardUid": e.uid,
        "event": (e.event === "arrival" || e.event === "in") ? "in" : "out",
        "timestamp": e.timestamp
    }))
};

msg.url = global.get("server_host") + global.get("batch_path");
msg.requestTimeout = 5000;

let token = global.get("accessToken");
msg.headers = {
    "Authorization": "Bearer " + token,
    "Content-Type": "application/json"
};
let logBatch = "=== BATCH OFFLINE PAYLOAD SENT TO SERVER ===\n" + JSON.stringify(msg.payload, null, 2);

node.log(logBatch);
node.status({ fill: "blue", shape: "dot", text: "Syncing " + events.length + " events" });
return [msg, null];

if (msg.statusCode === 201 && msg.payload && msg.payload.status === "OK") {
    let sql = "DELETE FROM attendance WHERE id IN (" + msg.event_ids.join(",") + ")";
    node.status({fill:"green", shape:"dot", text:"Batch Synced"});
    return [{ topic: sql }, { type: "sync_success" }];
}

node.status({fill:"red", shape:"ring", text:"Sync Failed"});
return [null, { type: "sync_fail" }];

let interval = context.get('interval') || 300;
let lastStatus = context.get('lastStatus') || "hb_success";
let timer = context.get('timer');
let visualTimer = context.get('visualTimer');

function clearAllTimers() {
    if (timer) clearTimeout(timer);
    if (visualTimer) clearInterval(visualTimer);
}

if (msg.payload === "HB_TRIGGER" || msg.force === true) {
    clearAllTimers();
    node.send({ payload: "check" });
    node.status({fill:"blue", shape:"dot", text:"Checking now..."});
    return null;
}

if (msg.type === "hb_success") {
    interval = 300; 
    lastStatus = "hb_success";
} else if (msg.type === "hb_fail") {
    if (lastStatus === "hb_success") {
        interval = 10; 
    } else {
        interval = Math.min(interval * 2, 300);
    }
    lastStatus = "hb_fail";
}

clearAllTimers();
let targetTime = Date.now() + (interval * 1000);
let statusColor = (interval === 300) ? "green" : "yellow";

visualTimer = setInterval(() => {
    let remaining = Math.ceil((targetTime - Date.now()) / 1000);
    if (remaining >= 0) {
        node.status({fill: statusColor, shape:"ring", text: "Next check in " + remaining + "s"});
    } else {
        clearInterval(visualTimer);
    }
}, 1000);

timer = setTimeout(() => {
    node.send({ payload: "check" });
}, interval * 1000);

context.set('interval', interval);
context.set('lastStatus', lastStatus);
context.set('timer', timer);
context.set('visualTimer', visualTimer);
return null;

msg.url = global.get("server_host") + global.get("health_path");
msg.requestTimeout = 5000;
return msg;

let lastStatus = global.get("server_online");
let currentStatus = (msg.statusCode === 200);

global.set("server_online", currentStatus);

if (currentStatus) {
    node.status({fill:"green", shape:"dot", text:"Server Online"});
    let out = [{ type: "hb_success" }, { type: "sync_success" }];
    if (lastStatus === false) out.push({ payload: "PUSH_STATUS" });
    return out;
} else {
    node.status({fill:"red", shape:"dot", text:"Server Offline"});
    let out = [{ type: "hb_fail" }, null];
    if (lastStatus === true) out.push({ payload: "PUSH_STATUS" });
    return out;
}

try {
    let trimmed = msg.payload.trim();
    if (trimmed.startsWith('{')) {
        msg.payload = JSON.parse(trimmed);
        node.status({fill:"green", shape:"dot", text:"JSON OK"});
        return msg;
    }
} catch (e) {}

node.status({fill:"red", shape:"dot", text:"Invalid Data"});
return null;

if (msg.payload.type === "system") {
    return [null, { payload: "HB_TRIGGER" }];
}

if (msg.payload.type === "attendance") {
    msg.saved_uid = msg.payload.uid;
    msg.saved_event = (msg.payload.event === "ARRIVAL") ? "in" : "out";
    msg.saved_timestamp = new Date().toISOString();

    msg.payload = {
        "cardUid": msg.saved_uid,
        "deviceUid": global.get("gateway_key"),
        "direction": msg.saved_event,
        "timestamp": msg.saved_timestamp
    };

    msg.url = global.get("server_host") + global.get("attendance_path");
    msg.requestTimeout = 5000;

    // let token = global.get("accessToken");
    // msg.headers = {
    //     "Authorization": "Bearer " + token,
    //     "Content-Type": "application/json"
    // };
    // let logMessage = "=== LIVE SCANNED PAYLOAD SENT TO SERVER ===\n" + JSON.stringify(msg.payload, null, 2);

    // node.log(logMessage);

    return [msg, null];
}
return null;

let now = new Date();
let hh = now.getHours().toString().padStart(2, '0');
let mm = now.getMinutes().toString().padStart(2, '0');
let ss = now.getSeconds().toString().padStart(2, '0');
let timeStr = hh + ":" + mm + ":" + ss;

function normalize(str) {
    if (!str) return "";
    return str.normalize("NFD")
              .replace(/[\u0300-\u036f]/g, "")
              .replace(/\|/g, "")
              .replace(/[^\x00-\x7F]/g, "");
}

if (msg.statusCode === 201 && msg.payload && msg.payload.success) {
    global.set("server_online", true);
    let first = normalize(msg.payload.name);
    let last = normalize(msg.payload.surname);
    const event = msg.payload.direction === 'in' ? 'ARRIVAL' : 'DEPARTURE';
    let out = "OK|" + event + "|" + first + "|" + last + "|" + timeStr + "\n";
    return [{ payload: out }, null, { type: "hb_success" }];
}

if (msg.statusCode === 404 && msg.payload && msg.payload.error === "Not Found") {
    global.set("server_online", true);
    return [{ payload: "DENIED\n" }, null, { type: "hb_success" }];
}

if (msg.statusCode >= 500) {
    global.set("server_online", true);
    return [{ payload: "SERVER_ERROR\n" }, null, { type: "hb_success" }];
}

global.set("server_online", false);
let rawEvent = (msg.saved_event || "").toLowerCase();
let offlineType = (rawEvent === 'auto') ? 'arrival' : rawEvent;
let sql = "INSERT INTO attendance (uid, event, timestamp) VALUES ('" + msg.saved_uid + "', '" + offlineType + "', '" + msg.saved_timestamp + "')";
let localOut = "LOCAL_OK|" + offlineType.toUpperCase() + "|" + msg.saved_uid + "|" + timeStr + "\n";
node.status({fill:"yellow", shape:"ring", text:"Offline - Triggering Heartbeat"});

let hbTrigger = { force: true };
return [{ payload: localOut }, { topic: sql }, hbTrigger];

let now = new Date();
let hh = now.getHours().toString().padStart(2, '0');
let mm = now.getMinutes().toString().padStart(2, '0');
let ss = now.getSeconds().toString().padStart(2, '0');
let status = global.get("server_online") ? "ON" : "OFF";
let result = "TIME|" + hh + ":" + mm + ":" + ss + "|" + status + "\n";
return { payload: result };
